import snapshot from './github-snapshot.json'

/**
 * Build-time GitHub snapshot. Generated by `scripts/fetch-github.mjs` and
 * committed — the site never calls the GitHub API at runtime, so an outage or
 * rate limit cannot affect the page. Re-run the script to refresh.
 */
export type GithubRepo = {
  name: string
  description: string | null
  url: string
  language: string | null
  stars: number
  topics: string[]
  pushedAt: string
}

export const githubUser: string = snapshot.user
export const githubGeneratedAt: string = snapshot.generatedAt
export const githubRepos: GithubRepo[] = snapshot.repos

/** Map a repo name to a case-study slug where one exists. */
export const repoSlugByName: Record<string, string> = {
  'smart-hospital-queue-system': 'smart-hospital-queue',
  'smarthealth-ai': 'smarthealth-ai',
  nova: 'nova',
  'antigravity-tracker': 'quotaverse',
  'Real-Time-Facial-Recognition-System-with-Assistant': 'facial-recognition',
  'Laboratory_managment-system-DBMS-': 'laboratory-management',
  'bed-occupancy-management': 'bed-occupancy',
  'Smart-Energy-Meter': 'smart-energy-meter',
  'Fingerprint-Door-Lock-System': 'fingerprint-door-lock',
  'Heart-Rate-Monitoring-System': 'heart-rate-monitoring',
}
